import{_ as e,c as r,o as t,ah as i}from"./chunks/framework.5ZZXabC7.js";const b=JSON.parse('{"title":"📚 학습 노트","description":"","frontmatter":{},"headers":[],"relativePath":"study/index.md","filePath":"study/index.md","lastUpdated":1756873256000}'),l={name:"study/index.md"};function n(h,a,o,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="📚-학습-노트" tabindex="-1">📚 학습 노트 <a class="header-anchor" href="#📚-학습-노트" aria-label="Permalink to “📚 학습 노트”">​</a></h1><blockquote><p>&quot;배운 건 정리해야 내 것이 된다!&quot;</p></blockquote><p>새로 배운 내용들을 나만의 방식으로 정리하는 공간입니다.<br> 딱딱한 문서보다는 개인 블로그 느낌으로 편하게 작성하되, 나중에 다시 봤을 때도 이해할 수 있도록 정리합니다.</p><h2 id="📝-작성된-학습-노트" tabindex="-1">📝 작성된 학습 노트 <a class="header-anchor" href="#📝-작성된-학습-노트" aria-label="Permalink to “📝 작성된 학습 노트”">​</a></h2><h3 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to “JavaScript”">​</a></h3><ul><li><strong><a href="./javascript-es6-features.html">JavaScript ES6+ 핵심 정리</a></strong> - 모던 JS 문법 정리</li></ul><h3 id="곧-추가될-노트들" tabindex="-1">곧 추가될 노트들 <a class="header-anchor" href="#곧-추가될-노트들" aria-label="Permalink to “곧 추가될 노트들”">​</a></h3><ul><li><strong>TypeScript 기초</strong> - 타입 시스템 이해하기</li><li><strong>React Hooks 패턴</strong> - 실무에서 자주 쓰는 패턴들</li><li><strong>Git 협업</strong> - 브랜치 전략과 PR 작성법</li><li><strong>Tailwind CSS</strong> - 유틸리티 클래스 활용법</li></ul><hr><h2 id="💡-내가-학습하는-방식" tabindex="-1">💡 내가 학습하는 방식 <a class="header-anchor" href="#💡-내가-학습하는-방식" aria-label="Permalink to “💡 내가 학습하는 방식”">​</a></h2><h3 id="_1-일단-써보기" tabindex="-1">1. 일단 써보기 <a class="header-anchor" href="#_1-일단-써보기" aria-label="Permalink to “1. 일단 써보기”">​</a></h3><p>새로운 기술을 배울 때 문서부터 읽지 않고, 간단한 예제부터 따라해봅니다.<br> 실제로 작동하는 걸 보면서 &quot;아, 이런 식으로 동작하는구나&quot; 하고 감을 잡는 편이에요.</p><h3 id="_2-궁금한-점-정리하기" tabindex="-1">2. 궁금한 점 정리하기 <a class="header-anchor" href="#_2-궁금한-점-정리하기" aria-label="Permalink to “2. 궁금한 점 정리하기”">​</a></h3><p>따라하다보면 &quot;왜 이렇게 되지?&quot; 싶은 부분들이 생겨요.<br> 그럴 때마다 따로 메모해두고, 나중에 하나씩 찾아보면서 정리합니다.</p><h3 id="_3-내-방식으로-정리하기" tabindex="-1">3. 내 방식으로 정리하기 <a class="header-anchor" href="#_3-내-방식으로-정리하기" aria-label="Permalink to “3. 내 방식으로 정리하기”">​</a></h3><p>공식 문서나 블로그들은 너무 딱딱한 경우가 많아서,<br> 내가 이해한 방식으로 다시 정리하는 편입니다. 그래야 나중에 다시 봐도 이해가 돼요.</p><h3 id="_4-실제-프로젝트에-적용하기" tabindex="-1">4. 실제 프로젝트에 적용하기 <a class="header-anchor" href="#_4-실제-프로젝트에-적용하기" aria-label="Permalink to “4. 실제 프로젝트에 적용하기”">​</a></h3><p>배운 건 바로 개인 프로젝트나 연습 프로젝트에 적용해봅니다.<br> 실제로 써보면서 &quot;아, 이럴 때 유용하구나&quot; 하고 체득하는 것 같아요.</p><h2 id="🔥-최근에-관심-있는-주제들" tabindex="-1">🔥 최근에 관심 있는 주제들 <a class="header-anchor" href="#🔥-최근에-관심-있는-주제들" aria-label="Permalink to “🔥 최근에 관심 있는 주제들”">​</a></h2><h3 id="next-js" tabindex="-1">Next.js <a class="header-anchor" href="#next-js" aria-label="Permalink to “Next.js”">​</a></h3><p>React를 어느 정도 익혔으니 이제 Next.js를 배워보고 싶어요.<br> SSR, API Routes 등 풀스택 개발에도 도전해보고 싶습니다.</p><h3 id="성능-최적화" tabindex="-1">성능 최적화 <a class="header-anchor" href="#성능-최적화" aria-label="Permalink to “성능 최적화”">​</a></h3><p>사용자가 체감할 수 있는 성능 개선에 관심이 많아졌어요.<br> 번들 사이즈 줄이기, 이미지 최적화, 로딩 시간 단축 등등.</p><h3 id="테스트-코드" tabindex="-1">테스트 코드 <a class="header-anchor" href="#테스트-코드" aria-label="Permalink to “테스트 코드”">​</a></h3><p>지금까지는 브라우저에서 직접 테스트하는 방식이었는데,<br> 자동화된 테스트 코드 작성법을 배우고 싶습니다.</p><hr><p><strong>📚 새로운 학습 노트가 계속 추가될 예정이니, 종종 들러주세요!</strong></p>',27)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
